#include <Arduino.h>

const uint8_t BUTTON_PIN = 3;
const uint8_t BUZZER_PIN = 9;
bool sounding = false;

void setup() {
  pinMode(BUTTON_PIN, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(BUZZER_PIN, LOW);
}

void loop() {
  bool pressed = digitalRead(BUTTON_PIN) == LOW;
  if (pressed && !sounding) {
    tone(BUZZER_PIN, 262);
    sounding = true;
  } else if (!pressed && sounding) {
    noTone(BUZZER_PIN);
    digitalWrite(BUZZER_PIN, LOW);
    sounding = false;
  }
}
